<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans;color:#17221c}h1{color:#176c4d}.head,.totals{display:flex;justify-content:space-between}.box{border:1px solid #ccd8d1;padding:18px;margin:20px 0}.totals{font-size:18px;border-top:2px solid #176c4d;padding-top:14px}small{color:#66736c}</style></head><body><div class="head"><div><h1>{{ $receipt->company->name }}</h1><small>Payment receipt</small></div><div><strong>{{ $receipt->receipt_number }}</strong><br>{{ $receipt->created_at->timezone($receipt->company->timezone)->format('d M Y H:i') }}</div></div><div class="box"><strong>{{ $receipt->payment->customer->name }}</strong><br>{{ $receipt->payment->customer->building->name }} / Room {{ $receipt->payment->customer->room->number }}<br>Passport: {{ $receipt->payment->customer->masked_passport }}</div><p>Payment mode: {{ ucfirst($receipt->payment->mode->value) }}<br>Collected by: {{ $receipt->payment->employee->name }}</p><div class="totals"><span>Amount received</span><strong>{{ $receipt->company->currency }} {{ number_format($receipt->payment->amount,2) }}</strong></div></body></html>
